// Dados 100% FICTÍCIOS de fundos (não use dados reais da empresa)
const CDI = 0.0551; // % ao dia útil, ilustrativo
const base = [
  { nome: "Fundo Renda DI", cotaOntem: 10.512340, varPct: 0.0560 },
  { nome: "Fundo Crédito Privado", cotaOntem: 10.298100, varPct: 0.0490 },
  { nome: "Fundo Multimercado", cotaOntem: 9.874500, varPct: 0.0890 }
];

const fundos = base.map(f => {
  const cotaHoje = +(f.cotaOntem * (1 + f.varPct / 100)).toFixed(6);
  const pctCDI = +((f.varPct / CDI) * 100).toFixed(1);
  return { fundo: f.nome, cotaOntem: f.cotaOntem, cotaHoje, variacaoDiaPct: f.varPct, pctDoCDI: pctCDI };
});

const prompt = `Você é analista de tesouraria. Com os dados fictícios abaixo, escreva um resumo diário em português, com no máximo 5 linhas, para um gestor financeiro.
Destaque o melhor e o pior fundo em % do CDI e avise se algum ficou abaixo de 100% do CDI. Use apenas os números fornecidos, sem inventar nada.

CDI do dia: ${CDI}%
Dados: ${JSON.stringify(fundos)}`;

return [{ json: { fundos, prompt } }];
